INSERT INTO hotels (id, name, city, address, description, rating, breakfast_available, image_url) VALUES
(1, 'The Shinjuku Grand View Hotel', 'Tokyo', '2-8-1 Nishi-Shinjuku, Shinjuku-ku, Tokyo 163-8001', 'Overlooking the vibrant Shinjuku skyline, this modern hotel offers panoramic city views, spacious western-style rooms, and instant access to Shinjuku Station.', 4.7, TRUE, 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1200&q=80'),
(2, 'Shibuya Crossing Boutique Stay', 'Tokyo', '1-12-3 Jinnan, Shibuya-ku, Tokyo 150-0041', 'Minimalist boutique hotel located a 3-minute stroll from Shibuya Scramble Crossing. Features contemporary minimalist aesthetics and high-speed fiber internet.', 4.5, FALSE, 'https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1200&q=80'),
(3, 'Ginza Heritage Palace Suites', 'Tokyo', '6-10-1 Ginza, Chuo-ku, Tokyo 104-0061', 'An upscale sanctuary in Tokyo''s premier luxury shopping and dining district, offering fine dining Japanese breakfasts and bespoke concierge services.', 4.9, TRUE, 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80'),
(4, 'Asakusa Riverside Ryokan Inn', 'Tokyo', '2-1-3 Hanakawado, Taito-ku, Tokyo 111-0033', 'Traditional Japanese hospitality with tatami mat flooring, cypress wood onsen baths, and tranquil views of the Sumida River and Tokyo Skytree.', 4.4, TRUE, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=1200&q=80'),
(5, 'Akihabara Tech Urban Pods & Rooms', 'Tokyo', '3-5-8 Sotokanda, Chiyoda-ku, Tokyo 101-0021', 'Futuristic and cost-effective urban hotel tailored for solo travelers and tech enthusiasts right in the heart of Electric Town.', 4.2, FALSE, 'https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?auto=format&fit=crop&w=1200&q=80'),
(6, 'Roppongi Skyline Tower Hotel', 'Tokyo', '6-10-3 Roppongi, Minato-ku, Tokyo 106-0032', 'High-rise luxury hotel boasting floor-to-ceiling windows with unobstructed views of Tokyo Tower, rooftop bar, and an open-air heated pool.', 4.8, TRUE, 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=1200&q=80'),
(7, 'Ueno Park Blossom Hotel', 'Tokyo', '1-59 Ueno-koen, Taito-ku, Tokyo 110-0007', 'Peaceful retreat steps away from Ueno Park and premier museums. Great for families and culture lovers seeking quiet surroundings.', 4.1, TRUE, 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=1200&q=80'),
(8, 'Tokyo Bay Panorama Resort', 'Tokyo', '1-9-1 Daiba, Minato-ku, Tokyo 135-8625', 'Spacious coastal hotel situated in Odaiba overlooking Rainbow Bridge, complete with wellness spa, international buffet, and family entertainment.', 4.6, TRUE, 'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1200&q=80'),
(9, 'Gion Traditional Machiya Residence', 'Kyoto', '570 Gionmachi Minamigawa, Higashiyama-ku, Kyoto 605-0074', 'Authentic restored wooden machiya townhouse combining historic Edo craftsmanship with modern luxury, authentic tea ceremonies, and kaiseki breakfast.', 4.9, TRUE, 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1200&q=80'),
(10, 'Kyoto Central Station Plaza Hotel', 'Kyoto', 'Higashishiokoji-cho, Shimogyo-ku, Kyoto 600-8216', 'Ultra-convenient modern hotel connected directly to Kyoto Station, featuring efficient transit links for exploring Kansai and full morning buffet.', 4.3, TRUE, 'https://images.unsplash.com/photo-1568495248636-6432b97bd949?auto=format&fit=crop&w=1200&q=80'),
(11, 'Arashiyama Bamboo Garden Inn', 'Kyoto', '12 Sagatenryuji Susukinobaba-cho, Ukyo-ku, Kyoto 616-8385', 'Serene ryokan nestled next to the world-famous Arashiyama Bamboo Grove. Includes private hot spring baths and traditional seasonal cuisine.', 4.8, TRUE, 'https://images.unsplash.com/photo-1618773928121-c32242e63f39?auto=format&fit=crop&w=1200&q=80'),
(12, 'Kamo River Breeze Hotel', 'Kyoto', '345 Miyagawacho, Higashiyama-ku, Kyoto 605-0801', 'Refined riverside boutique hotel with private balconies overlooking the Kamo River, perfect for evening strolls and cherry blossom viewing.', 4.4, FALSE, 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?auto=format&fit=crop&w=1200&q=80'),
(13, 'Kyoto Imperial Sanctuary Hotel', 'Kyoto', '456 Karasuma-dori, Kamigyo-ku, Kyoto 602-8024', 'Quiet, dignified property adjacent to Kyoto Imperial Palace Gardens. Features landscaped zen rock gardens and organic farm-to-table breakfast.', 4.6, TRUE, 'https://images.unsplash.com/photo-1584132967334-10e028bd69f7?auto=format&fit=crop&w=1200&q=80'),
(14, 'Kawaramachi City Boutique Stay', 'Kyoto', '220 Kawaramachi-dori, Nakagyo-ku, Kyoto 604-8026', 'Stylish urban lifestyle hotel right in downtown Kyoto''s premier shopping arcade, surrounded by izakayas, artisan coffee shops, and local crafts.', 4.2, FALSE, 'https://images.unsplash.com/photo-1591088398332-8a7791972843?auto=format&fit=crop&w=1200&q=80'),
(15, 'Namba Dotonbori Lights Hotel', 'Osaka', '1-5-8 Dotonbori, Chuo-ku, Osaka 542-0071', 'Vibrant hotel located directly in the bustling Dotonbori entertainment district. Perfect for foodies wanting round-the-clock access to street food.', 4.5, FALSE, 'https://images.unsplash.com/photo-1512918728675-ed5a9ecdebfd?auto=format&fit=crop&w=1200&q=80'),
(16, 'Osaka Umeda Skyline Suites', 'Osaka', '1-1-3 Umeda, Kita-ku, Osaka 530-0001', 'Sleek executive hotel near Osaka Station with spacious modern suites, fitness center, high-floor executive lounge, and Japanese-Western fusion breakfast.', 4.7, TRUE, 'https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&q=80'),
(17, 'Shinsaibashi Urban Oasis Stay', 'Osaka', '2-4-9 Minamisenba, Chuo-ku, Osaka 542-0081', 'Contemporary hotel with minimalist Scandinavian-Japanese decor, botanical lobby lounge, and fresh pastry breakfast.', 4.3, TRUE, 'https://images.unsplash.com/photo-1596394516093-501ba68a0ba6?auto=format&fit=crop&w=1200&q=80'),
(18, 'Osaka Castle Garden Hotel', 'Osaka', '1-1 Osakajo, Chuo-ku, Osaka 540-0002', 'Scenic hotel facing Osaka Castle Park with lush parkland views, serene Japanese tearoom, and extensive breakfast banquet.', 4.6, TRUE, 'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?auto=format&fit=crop&w=1200&q=80'),
(19, 'Tennoji Park Modern Inn', 'Osaka', '5-55 Chausuyama-cho, Tennoji-ku, Osaka 543-0063', 'Affordable, clean, and cheerful budget hotel near Tennoji Park and Abeno Harukas observatory. Excellent transport connectivity to Kansai Airport.', 4.0, FALSE, 'https://images.unsplash.com/photo-1590490359683-658d3d23f972?auto=format&fit=crop&w=1200&q=80'),
(20, 'Shin-Osaka Express Transit Hotel', 'Osaka', '5-14-10 Nishinakajima, Yodogawa-ku, Osaka 532-0011', 'Designed for Shinkansen travelers with seamless check-in, soundproofed rooms, comfortable work desks, and express hot breakfast.', 4.2, TRUE, 'https://images.unsplash.com/photo-1566665797739-1674de7a421a?auto=format&fit=crop&w=1200&q=80');
INSERT INTO rooms (id, hotel_id, room_type, capacity, price_per_night, total_rooms, description) VALUES
(1, 1, 'Standard Single Room', 1, 9500.00, 8, 'Compact 18m² room with a semi-double bed, ergonomic desk, and city view.'),(2, 1, 'Superior Double Room', 2, 14000.00, 6, 'Comfortable 24m² room with queen bed, high-speed WiFi, and rainforest shower.'),(3, 1, 'Deluxe Twin Room', 3, 18500.00, 4, 'Spacious 30m² room with two semi-double beds and sofa bed for 3 guests.'),(4, 1, 'Executive Skyline Suite', 4, 32000.00, 2, 'Luxury 50m² suite on the top floors with panoramic views of Tokyo skyline.'),(5, 2, 'Compact Urban Room', 1, 8500.00, 10, 'Minimalist 15m² room with custom soundproofing and ultra-fast fiber WiFi.'),(6, 2, 'Deluxe Queen Room', 2, 12500.00, 8, 'Stylish 22m² room featuring a queen bed and designer industrial aesthetic.'),(7, 2, 'Friends & Family Quad', 4, 22000.00, 3, 'Spacious 35m² room with 4 custom capsule bunks and lounge nook.'),(8, 3, 'Superior Queen Room', 2, 22000.00, 6, 'Elegantly appointed 28m² room with premium Simmons mattress and marble bathroom.'),(9, 3, 'Deluxe Executive Suite', 3, 35000.00, 4, 'Opulent 48m² suite with separate sitting room and complimentary minibar.'),(10, 3, 'Imperial Family Suite', 6, 48000.00, 2, 'Grand 75m² suite accommodating up to 6 guests with dining table and dual baths.'),(11, 4, 'Traditional Tatami Single', 1, 8000.00, 6, 'Authentic 12-jo tatami room with futon bedding and cedar fragrance.'),(12, 4, 'Japanese Riverview Double', 2, 13500.00, 8, 'Tatami room with low wooden furniture and window looking out on Sumida River.'),(13, 4, 'Family Tatami Suite', 5, 26000.00, 3, 'Large traditional room with multiple futons, tea table, and private wooden bath.'),(14, 5, 'Solo Tech Pod Room', 1, 6500.00, 12, 'Private micro-room with smart ambient lighting, 4K monitor, and charging hub.'),(15, 5, 'Standard Double Room', 2, 9800.00, 8, 'Modern 18m² room with double bed and smart TV streaming setup.'),(16, 6, 'Skyline Deluxe King', 2, 26000.00, 6, 'Luxurious 32m² room with king bed and sweeping views of Tokyo Tower.'),(17, 6, 'Tower Premium Suite', 4, 42000.00, 3, 'Expansive 60m² suite with living area, deep-soaking bathtub, and wine fridge.'),(18, 7, 'Parkside Single Room', 1, 7800.00, 8, 'Quiet 16m² single room with green park glimpses and work station.'),(19, 7, 'Standard Double Room', 2, 11500.00, 6, '20m² double room with comfortable bedding and complimentary green tea.'),(20, 7, 'Family Triple Room', 3, 16000.00, 4, '28m² triple room with three twin beds, ideal for friends and small families.'),(21, 8, 'Bay View Double Room', 2, 18000.00, 8, '26m² room with private balcony looking out onto Tokyo Bay and Rainbow Bridge.'),(22, 8, 'Resort Family Quad', 4, 29000.00, 4, 'Spacious 42m² room with 2 queen beds and spacious bathroom with deep tub.'),(23, 9, 'Machiya Courtyard Double', 2, 24000.00, 5, 'Restored heritage room with view of a private moss zen garden and cypress tub.'),(24, 9, 'Heritage Family Suite', 5, 45000.00, 2, 'Two-story traditional townhouse suite with wooden beams and hand-painted fusuma screens.'),(25, 10, 'Station Single Room', 1, 8500.00, 10, 'Efficient 16m² single room equipped with luggage storage and sound insulation.'),(26, 10, 'Comfort Double Room', 2, 12000.00, 8, '22m² room with double bed, air purifier, and electric kettle.'),(27, 10, 'Deluxe Family Twin', 4, 19500.00, 4, '32m² room with two double beds for families visiting Kyoto temples.'),(28, 11, 'Bamboo View Tatami Room', 2, 21000.00, 6, 'Traditional tatami room with shoji screens facing the quiet bamboo groves.'),(29, 11, 'Deluxe Ryokan Onsen Suite', 4, 38000.00, 3, 'Authentic suite featuring a private outdoor cedar onsen bath and seasonal yukatas.'),(30, 12, 'Riverside Single', 1, 9000.00, 6, 'Bright 18m² room with river view balcony and quiet study corner.'),(31, 12, 'Riverside Double Room', 2, 13500.00, 7, '24m² double room with balcony chairs overlooking the Kamo River walkway.'),(32, 12, 'Riverside Family Room', 4, 23000.00, 3, '36m² family room with 2 queen beds and mini refrigerator.'),(33, 13, 'Zen Garden Double', 2, 17500.00, 6, '26m² room overlooking peaceful stone garden, includes green tea set.'),(34, 13, 'Imperial Suite', 4, 34000.00, 2, '52m² suite with living room, tatami lounge corner, and luxury toiletries.'),(35, 14, 'Urban Queen Room', 2, 9800.00, 8, '20m² contemporary room with queen bed, smart mirror, and rainfall shower.'),(36, 14, 'City Twin Room', 3, 14500.00, 5, '26m² room with twin beds and sofa bed near downtown shopping.'),(37, 15, 'Dotonbori Economy Double', 2, 10000.00, 8, '20m² double room with blackout curtains and vibrant pop art decor.'),(38, 15, 'Dotonbori Triple Room', 3, 15000.00, 6, '28m² room with three single beds, great for food tour travelers.'),(39, 15, 'Friends Quad Suite', 4, 19500.00, 4, '36m² room with 2 bunk-queen configurations and dining table.'),(40, 16, 'Executive Single Room', 1, 11000.00, 8, '20m² room with high-floor city views and dedicated executive work station.'),(41, 16, 'Skyline Double Room', 2, 19500.00, 6, '30m² luxury room with king bed and floor-to-ceiling glass wall.'),(42, 16, 'Skyline Presidential Suite', 4, 39000.00, 2, '65m² suite with separate meeting/dining salon and whirlpool bath.'),(43, 17, 'Oasis Queen Room', 2, 12000.00, 8, '22m² room with natural wood tones, memory foam mattress, and coffee maker.'),(44, 17, 'Oasis Deluxe Twin', 3, 16500.00, 5, '28m² room with twin beds and sleeper couch.'),(45, 18, 'Castle View Double', 2, 15500.00, 7, '26m² room with direct vistas of Osaka Castle keep and park greens.'),(46, 18, 'Garden Family Suite', 5, 29500.00, 3, '45m² suite with 2 double beds + futon corner for up to 5 guests.'),(47, 19, 'Budget Single Room', 1, 5500.00, 10, '14m² compact, clean room with private ensuite shower and desk.'),(48, 19, 'Budget Double Room', 2, 8000.00, 8, '18m² double room offering great value and easy airport access.'),(49, 20, 'Express Single Room', 1, 7500.00, 10, '16m² single room with soundproof glass, iron, and luggage rack.'),(50, 20, 'Express Double Room', 2, 9500.00, 8, '20m² double room with queen bed and quick elevator access.');
